#!/usr/bin/env -S uv run --script
# /// script
# requires-python = ">=3.12"
# dependencies = []
# ///
"""Derive the checked-in game API manifest from the generated editor stub."""

from __future__ import annotations

import argparse
import ast
import json
import sys
from collections import defaultdict
from pathlib import Path
from typing import Any


RUFF_START = "# game-api: start"
RUFF_END = "# game-api: end"


def parse_arguments() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--header",
        type=Path,
        default=Path("Save0/__builtins__.py"),
        help="Generated game editor stub (default: Save0/__builtins__.py).",
    )
    parser.add_argument(
        "--manifest",
        type=Path,
        default=Path("game-api.json"),
        help="Committed API manifest (default: game-api.json).",
    )
    parser.add_argument(
        "--ruff-config",
        type=Path,
        default=Path("ruff.toml"),
        help="Ruff configuration containing the generated globals block.",
    )
    parser.add_argument(
        "--check",
        action="store_true",
        help="Report stale generated files instead of updating them.",
    )
    return parser.parse_args()


def public(name: str) -> bool:
    return not name.startswith("_")


def positional_signature(node: ast.FunctionDef) -> dict[str, int | None]:
    positional = [*node.args.posonlyargs, *node.args.args]
    return {
        "min_positional": len(positional) - len(node.args.defaults),
        "max_positional": None if node.args.vararg else len(positional),
    }


def assigned_names(node: ast.Assign | ast.AnnAssign | ast.TypeAlias) -> list[str]:
    if isinstance(node, ast.TypeAlias):
        return [node.name.id] if isinstance(node.name, ast.Name) and public(node.name.id) else []

    targets: list[ast.expr]
    if isinstance(node, ast.Assign):
        targets = node.targets
    else:
        targets = [node.target]
    return [target.id for target in targets if isinstance(target, ast.Name) and public(target.id)]


def build_manifest(header: Path) -> dict[str, Any]:
    tree = ast.parse(header.read_text(encoding="utf-8"), filename=str(header))
    functions: defaultdict[str, list[dict[str, int | None]]] = defaultdict(list)
    enums: dict[str, list[str]] = {}
    globals_: set[str] = set()

    for node in tree.body:
        if isinstance(node, ast.FunctionDef) and public(node.name):
            signature = positional_signature(node)
            if signature not in functions[node.name]:
                functions[node.name].append(signature)
            globals_.add(node.name)
        elif isinstance(node, ast.ClassDef) and public(node.name):
            globals_.add(node.name)
            if any(isinstance(base, ast.Name) and base.id == "_Enum" for base in node.bases):
                enums[node.name] = sorted(
                    member.target.id
                    for member in node.body
                    if isinstance(member, ast.AnnAssign)
                    and isinstance(member.target, ast.Name)
                    and public(member.target.id)
                )
        elif isinstance(node, (ast.Assign, ast.AnnAssign, ast.TypeAlias)):
            globals_.update(assigned_names(node))

    ordered_functions = {
        name: sorted(
            signatures,
            key=lambda signature: (
                signature["min_positional"],
                signature["max_positional"] is None,
                signature["max_positional"] or 0,
            ),
        )
        for name, signatures in sorted(functions.items())
    }
    return {
        "schema_version": 1,
        "source": "__builtins__.py",
        "globals": sorted(globals_),
        "functions": ordered_functions,
        "enums": dict(sorted(enums.items())),
    }


def render_manifest(manifest: dict[str, Any]) -> str:
    return json.dumps(manifest, indent=2, sort_keys=True) + "\n"


def render_ruff_block(globals_: list[str]) -> str:
    lines = [
        RUFF_START,
        "# Generated by scripts/sync_game_api.py; do not edit this block.",
        "builtins = [",
        *(f'    "{name}",' for name in globals_),
        "]",
        RUFF_END,
    ]
    return "\n".join(lines)


def replace_ruff_block(source: str, block: str) -> str:
    try:
        start = source.index(RUFF_START)
        end = source.index(RUFF_END, start) + len(RUFF_END)
    except ValueError as error:
        raise ValueError(f"ruff config must contain {RUFF_START!r} and {RUFF_END!r}") from error
    return source[:start] + block + source[end:]


def check_or_write(path: Path, expected: str, check: bool) -> bool:
    current = path.read_text(encoding="utf-8") if path.is_file() else None
    if current == expected:
        return True
    if check:
        print(f"stale generated file: {path}", file=sys.stderr)
        return False
    path.write_text(expected, encoding="utf-8")
    print(f"updated {path}")
    return True


def main() -> int:
    arguments = parse_arguments()

    if arguments.header.is_file():
        manifest = build_manifest(arguments.header)
        manifest_ok = check_or_write(arguments.manifest, render_manifest(manifest), arguments.check)
    elif arguments.check and arguments.manifest.is_file():
        manifest = json.loads(arguments.manifest.read_text(encoding="utf-8"))
        manifest_ok = True
        print(f"header unavailable; checked committed manifest: {arguments.manifest}")
    else:
        print(f"generated game header not found: {arguments.header}", file=sys.stderr)
        return 2

    try:
        ruff_source = arguments.ruff_config.read_text(encoding="utf-8")
        expected_ruff = replace_ruff_block(ruff_source, render_ruff_block(manifest["globals"]))
    except (OSError, KeyError, TypeError, ValueError) as error:
        print(f"cannot update Ruff globals: {error}", file=sys.stderr)
        return 2

    ruff_ok = check_or_write(arguments.ruff_config, expected_ruff, arguments.check)
    if manifest_ok and ruff_ok:
        if arguments.check:
            print("Game API manifest and Ruff globals are current.")
        return 0
    print("Run `just api-sync` after the game regenerates __builtins__.py.", file=sys.stderr)
    return 1


if __name__ == "__main__":
    raise SystemExit(main())
